/* Beyond One and the brands' logos for the decks (made by js/make_brand.py from assets/brand): PNG bytes with their size. */
'use strict';
const BoLogos = (() => {
const b = s => { const t = atob(s), u = new Uint8Array(t.length); for (let i = 0; i < t.length; i++) u[i] = t.charCodeAt(i); return u; };
const L = {
  stackedBlack: { w: 300, h: 457, b64: '' },
  stackedWhite: { w: 300, h: 457, b64: '' },
  black: { w: 560, h: 156, b64: '' },
  white: { w: 560, h: 156, b64: '' },
  mark: { w: 160, h: 160, b64: '' },
  virgin: { w: 480, h: 270, b64: '' },
  friendi: { w: 480, h: 277, b64: '' },
  fpay: { w: 480, h: 277, b64: '' },
};
// each picture decoded once and then the same bytes every time, so a deck keeps it once however many slides show it
const out = {}; for (const k of Object.keys(L)) { let u = null; out[k] = { w: L[k].w, h: L[k].h, get png() { return u || (u = b(L[k].b64)); }, dataUrl: 'data:image/png;base64,' + L[k].b64 }; }
return out;
})();
if (typeof module !== 'undefined') module.exports = BoLogos;
